import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

class Book {
    private String code;
    private String title;
    private int year;

    Book(String code, String title, int year) {
        this.code = code;
        this.title = title;
        this.year = year;
    }

    String getCode() {
        return code;
    }

    String getTitle() {
        return title;
    }

    int getYear() {
        return year;
    }
}

class Catalog {
    private Map<String, Book> books = new HashMap<>();

    void add(Book b) {
        books.put(b.getCode(), b);
    }

    Book findByCode(String code) {
        return books.get(code);
    }

    int size() {
        return books.size();
    }

    List<Book> sortedByYearDesc() {
        // Salin books.values() ke ArrayList, lalu urutkan: tahun terbit terbaru lebih dulu; bila tahun sama, urut judul A ke Z (Comparator).
        return new ArrayList<>(books.values());
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Catalog catalog = new Catalog();
        int n = Integer.parseInt(in.nextLine().trim());
        for (int i = 0; i < n; i++) {
            String[] p = in.nextLine().split(";");
            catalog.add(new Book(p[0].trim(), p[1].trim(), Integer.parseInt(p[2].trim())));
        }
        System.out.println("Katalog urut tahun terbaru:");
        for (Book b : catalog.sortedByYearDesc()) {
            System.out.println("- " + b.getTitle() + " (" + b.getYear() + ") [" + b.getCode() + "]");
        }
        System.out.println("Total judul: " + catalog.size());
        while (in.hasNextLine()) {
            String code = in.nextLine().trim();
            if (code.equals("selesai")) {
                break;
            }
            Book b = catalog.findByCode(code);
            System.out.println(b == null ? "Tidak ada: " + code : "Ditemukan: " + b.getTitle());
        }
    }
}
